/**
 * Registers the Workbox service worker generated by vite-plugin-pwa (registerType
 * 'autoUpdate': the new worker skips waiting and claims clients). We register it by hand
 * instead of `virtual:pwa-register` because that needs the `workbox-window` package, which
 * is not a dependency of this app.
 *
 * When an updated worker takes control, reload once so the page matches the new assets.
 * Service workers need HTTPS; over plain HTTP this does nothing (SPEC §4.4).
 */
export async function registerServiceWorker(
  nav: Navigator = navigator,
  reload: () => void = () => window.location.reload(),
): Promise<void> {
  const sw = nav.serviceWorker;
  if (!sw) return;
  const hadController = sw.controller !== null && sw.controller !== undefined;
  let reloading = false;
  sw.addEventListener('controllerchange', () => {
    if (!hadController || reloading) return;
    reloading = true;
    reload();
  });
  try {
    const registration = await sw.register('/sw.js', { scope: '/' });
    // Check for updates when the app comes back to the foreground.
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') void registration.update?.().catch(() => {});
    });
  } catch (e) {
    console.warn('service worker registration failed', e);
  }
}
